head.script:
requires("uiplugin.popup");
scwin.btn_browserPopup3_onclick = function() {
	var options = {
		id: "browserPopup3",
		type: "wframePopup",
		popupName: "직원 조회",
		windowHeaderHTML: "<span style='color:red;'> windowHeaderHTML </span>",
		width: 560,
		height: 500,
		top: "167px",
		left: "100px",
		modal: false,
		frameModal: $p.getFrameId()
	};
	$p.openPopup("WESD_462_tabcontrol_itemTable_position.xml", options);
};
scwin.checkVal1 = function() {
	return document.getElementById('mf_browserPopup3_header').innerText == 'windowHeaderHTML';
};
scwin.checkVal2 = function() {
	return document.getElementById('mf_browserPopup3_header').querySelector('span').style.color == 'red';
};
